import { Meta, StoryObj } from "@storybook/react";
import CalendarDateField from "./calendar-date-field";
import dayjs from "dayjs";
import { action } from "storybook/actions";
import { DateHelper } from "@/core/helpers";

const FAKE_START_DATE = "2023-05-01";

const today = dayjs(FAKE_START_DATE);
const firstDate = DateHelper.toStringYYYYMMDD(today);
const lastDate = DateHelper.toStringYYYYMMDD(today.add(20, "day"));
const extraDay = today.add(25, "day");

const meta = {
  title: "Primitives/Calendar/CalendarDateField",
  component: CalendarDateField,
} satisfies Meta<typeof CalendarDateField>;

export default meta;

export const Primary = {
  args: {
    calendarDates: {
      selectedDates: [
        {
          date: DateHelper.toStringYYYYMMDD(extraDay),
          fullDate: DateHelper.toStringYYYYMMDD(extraDay),
        },
      ],
      startDate: firstDate,
      endDate: lastDate,
    },
    onChangeDate: action("Clicked date"),
    removeDaysInThePast: false,
  },
} satisfies StoryObj<typeof meta>;

const bookedExtraDay = today.add(15, "day");
const bookedStartDate = DateHelper.toStringYYYYMMDD(today.add(2, "day"));
const bookedEndDate = DateHelper.toStringYYYYMMDD(today.add(5, "day"));

export const WithFullyBookedDates = {
  args: {
    ...Primary.args,
    fullyBookedDates: {
      selectedDates: [
        {
          date: DateHelper.toStringYYYYMMDD(bookedExtraDay),
          fullDate: DateHelper.toStringYYYYMMDD(bookedExtraDay),
        },
      ],
      startDate: bookedStartDate,
      endDate: bookedEndDate,
    },
  },
} satisfies StoryObj<typeof meta>;
